def transform(grid):
    h, w = len(grid), len(grid[0])
    target = min(r for r in range(h) if 8 in grid[r])
    tops = {v:min(r for r in range(h) if v in grid[r]) for v in {x for row in grid for x in row if x}}
    out = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v:
                nr=r+(target-tops[v])
                if nr<h: out[nr][c]=v
    return out
